#include <iostream>
#include <algorithm>
#include <cstdio>
#include <cstring>
using namespace std;

int totalN, totalK, totalP;

int modExp(int base, int exp) {
    int res = 1;
    int cur = base;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * cur % totalP;
        cur = (long long)cur * cur % totalP;
        exp >>= 1;
    }
    return res;
}

int getLowestBit(int x) {
    return x & (-x);
}

int memoArr[26][250010];
int factArr[250010], invFactArr[250010];

void setupFactors() {
    factArr[0] = 1;
    for (int i = 1; i <= totalN; ++i)
        factArr[i] = (long long)factArr[i - 1] * i % totalP;
    invFactArr[totalN] = modExp(factArr[totalN], totalP - 2);
    for (int i = totalN; i >= 1; --i)
        invFactArr[i - 1] = (long long)invFactArr[i] * i % totalP;
}

int recursiveSolve(int current, int S) {
    if (memoArr[current][S] != -1) return memoArr[current][S];
    if (S == 0) {
        memoArr[current][S] = factArr[totalN];
        for (int i = 1; i <= current; ++i)
            memoArr[current][S] = (long long)memoArr[current][S] * (totalK - i + 1) % totalP;
        return memoArr[current][S];
    }
    memoArr[current][S] = 0;
    int U = S - getLowestBit(S);
    for (int T = U; T; T = (T - 1) & U)
        memoArr[current][S] = (memoArr[current][S] + (long long)invFactArr[S - T] * recursiveSolve(current + 1, T)) % totalP;
    memoArr[current][S] = (memoArr[current][S] + (long long)invFactArr[S] * recursiveSolve(current + 1, 0)) % totalP;
    return memoArr[current][S];
}

int main() {
    scanf("%d %d %d", &totalN, &totalK, &totalP);
    int answer = 1;
    for (int i = 1; i <= totalN; ++i)
        answer = (long long)answer * totalK % totalP;
    if (totalN % 2 == 0) {
        setupFactors();
        memset(memoArr, -1, sizeof(memoArr));
        answer = (answer - recursiveSolve(0, totalN) + totalP) % totalP;
    }
    printf("%d\n", answer);
    return 0;
}
